  link(SPIRIT_TREE.village, SPIRIT_TREE.varrock, "spirit_village_to_varrock", villageReq);
  link(SPIRIT_TREE.village, SPIRIT_TREE.stronghold, "spirit_village_to_stronghold", villageReq);
