// vendor/client-ts/src/config/VarpType.ts
init_Packet();

class VarpType {
  static numDefinitions = 0;
  static list = [];
  static codeCount = 0;
  static codeIds = null;
  type = 0;
  type2 = 0;
  transmit = false;
  keepBit = true;
  clientcode = 0;
  protect = false;
  unused7 = 0;
  scopeType = 0;
  scope = false;
  unused12 = -1;
  unused14 = true;
  debugname = "";
  static init(config) {
    const dat = new Packet(config.read("varp.dat"));
    this.codeCount = 0;
    this.numDefinitions = dat.g2();
    this.list = new Array(this.numDefinitions);
    this.codeIds = new Int32Array(this.numDefinitions);
    for (let id = 0;id < this.numDefinitions; id++) {
      if (!this.list[id]) {
        this.list[id] = new VarpType;
      }
      this.list[id].decode(id, dat);
    }
    if (dat.pos != dat.data.length) {
      console.log("varptype load mismatch");
    }
  }
  decode(id, dat) {
    while (true) {
      const code = dat.g1();
      if (code === 0) {
        return;
      }
      if (code === 1) {
        this.type = dat.g1();
      } else if (code === 2) {
        this.type2 = dat.g1();
      } else if (code === 3) {
        this.transmit = true;
        if (VarpType.codeIds) {
          VarpType.codeIds[VarpType.codeCount++] = id;
        }
      } else if (code === 4) {
        this.keepBit = false;
      } else if (code === 5) {
        this.clientcode = dat.g2();
      } else if (code === 6) {
        this.protect = true;
      } else if (code === 7) {
        this.unused7 = dat.g4();
      } else if (code === 8) {
        this.scopeType = 1;
        this.scope = true;
      } else if (code === 10) {
        this.debugname = dat.gjstr();
      } else if (code === 11) {
        this.scope = true;
      } else if (code === 12) {
        this.unused12 = dat.g4();
      } else if (code === 13) {
        this.scopeType = 2;
        this.scope = true;
      } else if (code === 14) {
        this.unused14 = false;
      } else {
        console.log("Error unrecognised config code: ", code);
      }
    }
  }
}

