  searchParams;
  constructor(nodeid, lowmem, members) {
    super();
    this.searchParams = new URLSearchParams(window.location.search);
    if (typeof nodeid === "undefined" || typeof lowmem === "undefined" || typeof members === "undefined") {
      return;
    }
    console.log(`RS2 user client - release #${CLIENT_VERSION2}`);
    Client2.nodeId = nodeid;
    Client2.memServer = members;
    if (lowmem) {
      Client2.setLowMem();
    } else {
      Client2.setHighMem();
    }
    this.run();
  }
  static setLowMem() {
    World.lowMem = true;
    Pix3D.lowMem = true;
    Client2.lowMem = true;
    ClientBuild.lowMem = true;
  }
  static setHighMem() {
    World.lowMem = false;
    Pix3D.lowMem = false;
    Client2.lowMem = false;
    ClientBuild.lowMem = false;
  }
  saveMidi(data, fading) {
    if (!this.midiActive) {
      return;
    }
    playMidi(data, this.midiVolume, fading);
  }
  getIntParam(name, fallback = 0) {
    const value = this.searchParams.get(name);
    if (value === null || !/^[+-]?\d+$/.test(value)) {
      return fallback;
    }
    const parsed = Number(value);
    return Number.isSafeInteger(parsed) ? parsed : fallback;
  }
  drawError() {
    canvas2d2.fillStyle = "black";
    canvas2d2.fillRect(0, 0, this.sWid, this.sHei);
    this.setFramerate(1);
    this.titleFlames?.close();
    let y = 0;
    if (this.errorLoading) {
      canvas2d2.font = "bold 16px helvetica, sans-serif";
      canvas2d2.textAlign = "left";
      canvas2d2.fillStyle = "yellow";
      y = 35;
      canvas2d2.fillText("Sorry, an error has occured whilst loading RuneScape", 30, y);
      y += 50;
      canvas2d2.fillStyle = "white";
      canvas2d2.fillText("To fix this try the following (in order):", 30, y);
      y += 50;
      canvas2d2.font = "bold 12px helvetica, sans-serif";
      canvas2d2.fillText("1: Try closing ALL open web-browser windows, and reloading", 30, y);
      y += 30;
      canvas2d2.fillText("2: Try clearing your web-browsers cache", 30, y);
      y += 30;
      canvas2d2.fillText("3: Try using a different game-world", 30, y);
      y += 30;
      canvas2d2.fillText("4: Try rebooting your computer", 30, y);
      y += 30;
      canvas2d2.fillText("5: Try selecting a different method from the play-game menu", 30, y);
    } else if (this.errorHost) {
      canvas2d2.font = "bold 20px helvetica, sans-serif";
      canvas2d2.textAlign = "left";
      canvas2d2.fillStyle = "white";
      y = 50;
      canvas2d2.fillText("Error - unable to load game!", 50, y);
      y += 50;
      canvas2d2.fillText("To play RuneScape make sure you play from", 50, y);
      y += 50;
      canvas2d2.fillText("An approved domain", 50, y);
    } else if (this.errorStarted) {
      canvas2d2.font = "bold 13px helvetica, sans-serif";
      canvas2d2.textAlign = "left";
      canvas2d2.fillStyle = "yellow";
      y = 35;
      canvas2d2.fillText("Error a copy of RuneScape already appears to be loaded", 30, y);
      y += 50;
      canvas2d2.fillStyle = "white";
      canvas2d2.fillText("To fix this try the following (in order):", 30, y);
      y += 50;
      canvas2d2.font = "bold 12px helvetica, sans-serif";
      canvas2d2.fillText("1: Try closing ALL open web-browser windows, and reloading", 30, y);
      y += 30;
      canvas2d2.fillText("2: Try rebooting your computer, and reloading", 30, y);
    }
    if (this.errorMessage) {
      y += 50;
      canvas2d2.fillStyle = "red";
      canvas2d2.fillText(this.errorMessage, 30, y);
    }
  }
  async getJagCrc() {
    let wait = 5;
    let retries = 0;
    this.jagChecksum[8] = 0;
    while (this.jagChecksum[8] === 0) {
      let error = "Unknown problem";
      await this.drawProgress("Connecting to web server", 10);
      try {
        const checksums = new Packet(await downloadUrl("/crc"));
        for (let i2 = 0;i2 < 9; i2++) {
          this.jagChecksum[i2] = checksums.g4();
        }
        const expected = checksums.g4();
        let calculated = 1234;
        for (let i2 = 0;i2 < 9; i2++) {
          calculated = (calculated << 1) + this.jagChecksum[i2] | 0;
        }
        if (expected !== calculated) {
          error = "checksum problem";
          this.jagChecksum[8] = 0;
        }
      } catch (err2) {
        error = "connection problem";
        this.jagChecksum[8] = 0;
      }
      if (this.jagChecksum[8] === 0) {
        retries++;
        for (let remaining = wait;remaining > 0; remaining--) {
          if (retries >= 10) {
            await this.drawProgress("Game updated - please reload page", 10);
            remaining = 10;
          } else {
            await this.drawProgress(`${error} - Will retry in ${remaining} secs.`, 10);
          }
          await sleep(1000);
        }
        wait *= 2;
        if (wait > 60) {
          wait = 60;
        }
      }
    }
  }
  async getJagFile(displayName, progress, filename, index) {
    const crc = this.jagChecksum[index];
    let data;
    let retry = 5;
    try {
      if (this.db) {
        data = await this.db.read(0, index);
      }
    } catch (_e) {}
    if (data && Packet.getcrc(data, 0, data.length) !== crc) {
      data = undefined;
    }
    if (data) {
      return new JagFile(data);
    }
    let loops = 0;
    while (!data) {
      await this.drawProgress(`Requesting ${displayName}`, progress);
      try {
        data = await downloadUrl(`/${filename}${crc}`);
        const checksum = Packet.getcrc(data, 0, data.length);
        if (crc === checksum) {
          try {
            if (this.db) {
              await this.db.write(0, index, data);
            }
          } catch (_e) {}
        } else {
          data = undefined;
          loops++;
        }
      } catch (_e) {
        data = undefined;
      }
      if (!data) {
        for (let i2 = retry;i2 > 0; i2--) {
          if (loops >= 3) {
            await this.drawProgress("Game updated - please reload page", progress);
            i2 = 10;
          } else {
            await this.drawProgress(`Error loading - Will retry in ${i2} secs.`, progress);
          }
          await sleep(1000);
        }
        retry *= 2;
        if (retry > 60) {
          retry = 60;
        }
      }
    }
    return new JagFile(data);
  }
