var CHEF_DOOR_IN_OUTSIDE = { x: 3079, z: 3083 };
var CHEF_DOOR_IN_INSIDE = { x: 3078, z: 3084 };
var CHEF_DOOR_OUT = { x: 3072, z: 3090 };
var CHEF_DOOR_OUT_INSIDE = { x: 3073, z: 3090 };
