// tools/harness/ui/confirmDialog.ts
function showConfirmDialog(opts) {
  const confirmLabel = opts.confirmLabel ?? "Yes";
  const cancelLabel = opts.cancelLabel ?? "No";
  const zIndex = opts.zIndex ?? 1300;
  return new Promise((resolve) => {
    const backdrop = el("div", "rs2b0t-modal-backdrop rs2b0t-confirm-backdrop");
    Object.assign(backdrop.style, {
      display: "flex",
      position: "fixed",
      inset: "0",
      background: "rgba(0,0,0,0.6)",
      alignItems: "center",
      justifyContent: "center",
      zIndex: String(zIndex)
    });
    const modal = el("div", "rs2b0t-modal rs2b0t-confirm-modal");
    Object.assign(modal.style, {
      width: "min(420px, 90vw)",
      maxHeight: "none",
      background: "#1a1a1a",
      border: "1px solid #555",
      borderRadius: "6px",
      padding: "14px 16px",
      fontFamily: "ui-monospace, Menlo, monospace"
    });
    const header = el("div", "rs2b0t-modal-header");
    const titleEl = el("div", "rs2b0t-modal-title");
    Object.assign(titleEl.style, { color: "#eee", fontWeight: "600", fontSize: "14px", marginBottom: "8px" });
    titleEl.textContent = opts.title;
    header.appendChild(titleEl);
    modal.appendChild(header);
    const body = el("div", "rs2b0t-confirm-body");
    Object.assign(body.style, {
      color: "#ccc",
      fontSize: "13px",
      lineHeight: "1.45",
      margin: "4px 0 12px",
      whiteSpace: "pre-wrap"
    });
    body.textContent = opts.body;
    modal.appendChild(body);
    let dontAsk = null;
    if (opts.dontAskAgainLabel) {
      const row2 = el("label", "rs2b0t-confirm-dont-ask");
      Object.assign(row2.style, {
        display: "flex",
        alignItems: "center",
        gap: "8px",
        color: "#bbb",
        fontSize: "12px",
        marginBottom: "14px",
        cursor: "pointer",
        userSelect: "none"
      });
      dontAsk = document.createElement("input");
      dontAsk.type = "checkbox";
      dontAsk.className = "rs2b0t-confirm-dont-ask-check";
      row2.appendChild(dontAsk);
      row2.appendChild(document.createTextNode(opts.dontAskAgainLabel));
      modal.appendChild(row2);
    }
    const actions2 = el("div", "rs2b0t-confirm-actions");
    Object.assign(actions2.style, {
      display: "flex",
      justifyContent: "flex-end",
      gap: "8px"
    });
    const noBtn = document.createElement("button");
    noBtn.type = "button";
    noBtn.className = "rs2b0t-button rs2b0t-confirm-no";
    noBtn.textContent = cancelLabel;
    const yesBtn = document.createElement("button");
    yesBtn.type = "button";
    yesBtn.className = "rs2b0t-button rs2b0t-confirm-yes";
    yesBtn.textContent = confirmLabel;
    Object.assign(yesBtn.style, {
      borderColor: "#a65c00",
      color: "#ffb74d"
    });
    actions2.appendChild(noBtn);
    actions2.appendChild(yesBtn);
    modal.appendChild(actions2);
    backdrop.appendChild(modal);
    document.body.appendChild(backdrop);
    let settled = false;
    const finish = (confirmed) => {
      if (settled) {
        return;
      }
      settled = true;
      window.removeEventListener("keydown", onKey, true);
      backdrop.remove();
      resolve({
        confirmed,
        dontAskAgain: Boolean(dontAsk?.checked)
      });
    };
    const onKey = (e) => {
      if (e.key === "Escape") {
        e.preventDefault();
        e.stopPropagation();
        finish(false);
      } else if (e.key === "Enter") {
        e.preventDefault();
        e.stopPropagation();
        finish(true);
      }
    };
    window.addEventListener("keydown", onKey, true);
    backdrop.addEventListener("click", (e) => {
      if (e.target === backdrop) {
        finish(false);
      }
    });
    noBtn.addEventListener("click", () => finish(false));
    yesBtn.addEventListener("click", () => finish(true));
    yesBtn.focus();
  });
}

// tools/harness/ui/basemapLocalCache.ts
var DB_NAME = "lc377-map-picker";
var DB_VERSION = 1;
var STORE = "basemap";
var ROW_KEY = "current";
async function fetchClientCrcKey() {
  try {
    const res = await fetch(new URL("/crc", typeof location !== "undefined" ? location.origin : "http://localhost"));
    if (!res.ok) {
      return null;
    }
    const bytes = new Uint8Array(await res.arrayBuffer());
    if (bytes.length < 36) {
      return null;
    }
    let key = "";
    for (let i3 = 0;i3 < 36; i3++) {
      key += bytes[i3].toString(16).padStart(2, "0");
    }
    return key;
  } catch {
    return null;
  }
}
function openDb() {
  return new Promise((resolve, reject) => {
    if (typeof indexedDB === "undefined") {
      reject(new Error("indexedDB unavailable"));
      return;
    }
    const req = indexedDB.open(DB_NAME, DB_VERSION);
    req.onerror = () => reject(req.error ?? new Error("idb open failed"));
    req.onsuccess = () => resolve(req.result);
    req.onupgradeneeded = () => {
      const db = req.result;
      if (!db.objectStoreNames.contains(STORE)) {
        db.createObjectStore(STORE);
      }
    };
  });
}
async function readBasemapLocalCache() {
  try {
    const db = await openDb();
    return await new Promise((resolve, reject) => {
      const tx = db.transaction(STORE, "readonly");
      const req = tx.objectStore(STORE).get(ROW_KEY);
      req.onsuccess = () => {
        const v = req.result;
        resolve(v && v.imageBlob && v.crcKey ? v : null);
      };
      req.onerror = () => reject(req.error);
      tx.oncomplete = () => db.close();
    });
  } catch {
    return null;
  }
}
async function writeBasemapLocalCache(rec) {
  const db = await openDb();
  await new Promise((resolve, reject) => {
    const tx = db.transaction(STORE, "readwrite");
    tx.objectStore(STORE).put(rec, ROW_KEY);
    tx.oncomplete = () => {
      db.close();
      resolve();
    };
    tx.onerror = () => reject(tx.error);
  });
}
async function clearBasemapLocalCache() {
  try {
    const db = await openDb();
    await new Promise((resolve, reject) => {
      const tx = db.transaction(STORE, "readwrite");
      tx.objectStore(STORE).delete(ROW_KEY);
      tx.oncomplete = () => {
        db.close();
        resolve();
      };
      tx.onerror = () => reject(tx.error);
    });
  } catch {}
}
async function imageSourceToPngBlob(image, width, height) {
  const c = document.createElement("canvas");
  c.width = width;
  c.height = height;
  const ctx = c.getContext("2d");
  if (!ctx) {
    throw new Error("2d context unavailable");
  }
  ctx.drawImage(image, 0, 0, width, height);
  const blob = await new Promise((resolve) => c.toBlob(resolve, "image/png"));
  if (!blob) {
    throw new Error("toBlob failed");
  }
  return blob;
}
async function blobToImage(blob) {
  if (typeof createImageBitmap === "function") {
    return createImageBitmap(blob);
  }
  const url = URL.createObjectURL(blob);
  try {
    return await new Promise((resolve, reject) => {
      const el2 = new Image;
      el2.onload = () => resolve(el2);
      el2.onerror = () => reject(new Error("image decode failed"));
      el2.src = url;
    });
  } finally {
    URL.revokeObjectURL(url);
  }
}
function prefsKeyFromBakePrefs(prefs) {
  return prefsFingerprint(prefs);
}
async function saveRegeneratedBasemapLocally(crcKey, prefs, manifest, image) {
  const w = manifest.sizeTiles.w * manifest.pixelsPerTile;
  const h = manifest.sizeTiles.h * manifest.pixelsPerTile;
  const imageBlob = await imageSourceToPngBlob(image, w, h);
  await writeBasemapLocalCache({
    crcKey,
    prefsKey: prefsKeyFromBakePrefs(prefs),
    manifest: { ...manifest, basemapUrl: "local-cache" },
    imageBlob,
    savedAt: Date.now()
  });
}

